"""
Evaluate all sweep CSVs using evaluate_csv.py and rank by mAP.
Uses the UrbAM inv split (Containers) as local proxy — same structure as Kaggle.

Usage:
    python eval_sweep.py
"""

import os
import subprocess
import re
import glob

SWEEP_DIR  = './submissions/sweep'
URBAM_PATH = '/media/DiscoLocal/IPCV/UE-ReID/UrbAM-ReID/ICIP_UrbAM-ReID/splits/Containers/containers/inv'
EVAL_SCRIPT = './evaluate_csv.py'

# Check the UrbAM eval dir has query.csv and test.csv
# These are generated by evaluate_urbam.py — check if they exist already
URBAM_EVAL_DIR = './urbam_eval_exp02'

if not os.path.exists(os.path.join(URBAM_EVAL_DIR, 'query.csv')):
    print(f"ERROR: {URBAM_EVAL_DIR}/query.csv not found.")
    print("Run evaluate_urbam.py first to generate the ground truth CSVs.")
    exit(1)

csvs = sorted(glob.glob(os.path.join(SWEEP_DIR, '*.csv')))
print(f"Found {len(csvs)} CSVs to evaluate...\n")

results = []
for i, csv_path in enumerate(csvs):
    fname = os.path.basename(csv_path)
    # Parse params from filename
    m = re.search(r'k1(\d+)_k2(\d+)_lam(\d+)', fname)
    if not m:
        continue
    k1, k2, lam_int = int(m.group(1)), int(m.group(2)), int(m.group(3))
    lam = lam_int / 10.0

    result = subprocess.run(
        ['python', EVAL_SCRIPT,
         '--path', URBAM_EVAL_DIR,
         '--track', csv_path],
        capture_output=True, text=True
    )
    output = result.stdout + result.stderr

    # Extract mAP from output
    map_match = re.search(r'mAP[:\s]+([0-9.]+)', output, re.IGNORECASE)
    if map_match:
        mAP = float(map_match.group(1))
        results.append((mAP, k1, k2, lam, fname))
        print(f"[{i+1:2d}/{len(csvs)}] k1={k1:2d} k2={k2:2d} lam={lam:.1f}  mAP={mAP:.5f}")
    else:
        print(f"[{i+1:2d}/{len(csvs)}] k1={k1:2d} k2={k2:2d} lam={lam:.1f}  FAILED to parse mAP")
        print(output[:300])

# Sort by mAP descending
results.sort(reverse=True)

print("\n" + "="*60)
print("TOP 10 RE-RANKING PARAMETER COMBINATIONS")
print("="*60)
print(f"{'Rank':>4} {'mAP':>8} {'k1':>4} {'k2':>4} {'lam':>5}  file")
for rank, (mAP, k1, k2, lam, fname) in enumerate(results[:10], 1):
    print(f"{rank:>4} {mAP:>8.5f} {k1:>4} {k2:>4} {lam:>5.1f}  {fname}")

print("\nBEST PARAMS:")
if results:
    best_mAP, best_k1, best_k2, best_lam, best_fname = results[0]
    print(f"  k1={best_k1}, k2={best_k2}, lambda={best_lam}  →  mAP={best_mAP:.5f}")
    print(f"  File: {os.path.join(SWEEP_DIR, best_fname)}")
    print(f"\nTo submit, use: submissions/sweep/{best_fname}")
